import { useState, type ReactNode } from 'react'
import { BarChart3, BookOpen, Boxes, ChevronDown, CreditCard, LayoutDashboard, Menu, Package, Receipt, Settings, Store, Truck, Users, X } from 'lucide-react'
import { Button } from '../ui/button'
import { cn } from '../../lib/utils'

export type VendorView = 'overview' | 'pos' | 'inventory' | 'catalog' | 'debt' | 'deliveries' | 'reports' | 'staff' | 'settings'

const operations: { id: VendorView; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard },
  { id: 'pos', label: 'Point of sale', icon: Receipt },
  { id: 'inventory', label: 'Inventory', icon: Boxes },
  { id: 'catalog', label: 'Catalog', icon: Package },
  { id: 'debt', label: 'Debt & credit', icon: CreditCard },
  { id: 'deliveries', label: 'Deliveries', icon: Truck },
  { id: 'reports', label: 'Reports', icon: BarChart3 },
]

export function VendorShell({ view, onViewChange, onSignOut, username, vendors, stores, vendorId, storeId, onVendorChange, onStoreChange, isAdmin, children }: { view: VendorView; onViewChange: (view: VendorView) => void; onSignOut: () => void; username: string; vendors: { id: number; name: string }[]; stores: { id: number; vendorId: number; name: string; code: string }[]; vendorId?: number; storeId?: number; onVendorChange: (id: number) => void; onStoreChange: (id: number) => void; isAdmin: boolean; children: ReactNode }) {
  const [open, setOpen] = useState(false)
  const currentVendor = vendors.find(item => item.id === vendorId) ?? vendors[0]
  const availableStores = stores.filter(store => store.vendorId === currentVendor?.id)
  function navigate(next: VendorView) { onViewChange(next); setOpen(false) }
  return <div className="min-h-screen bg-slate-100 text-slate-950"><aside className={cn('fixed inset-y-0 left-0 z-40 flex w-64 flex-col border-r border-slate-200 bg-slate-950 text-white transition-transform lg:translate-x-0', open ? 'translate-x-0' : '-translate-x-full')}><div className="flex h-16 items-center justify-between border-b border-white/10 px-4"><div className="flex items-center gap-2.5"><span className="grid size-8 place-items-center rounded-lg bg-indigo-400 text-xs font-black text-slate-950">TK</span><div><strong className="block text-sm">TindaKart</strong><span className="block text-[9px] font-bold uppercase tracking-[.15em] text-slate-400">Store workspace</span></div></div><button className="lg:hidden" onClick={() => setOpen(false)} aria-label="Close menu"><X size={18} /></button></div><div className="flex-1 overflow-y-auto px-3 py-5"><p className="px-2 text-[9px] font-bold uppercase tracking-[.18em] text-slate-500">Operations</p><nav className="mt-2 space-y-0.5">{operations.map(item => { const Icon = item.icon; return <button key={item.id} onClick={() => navigate(item.id)} className={cn('flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2.5 text-left text-[13px] font-semibold transition', view === item.id ? 'bg-indigo-500 text-white shadow-lg shadow-indigo-950/20' : 'text-slate-400 hover:bg-white/10 hover:text-white')}><Icon size={16} />{item.label}</button> })}</nav>{isAdmin && <div className="mt-6 border-t border-white/10 pt-4"><p className="px-2 text-[9px] font-bold uppercase tracking-[.18em] text-slate-500">Administration</p><button onClick={() => navigate('staff')} className={cn('mt-2 flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2.5 text-left text-[13px] font-semibold text-slate-400 hover:bg-white/10 hover:text-white', view === 'staff' && 'bg-white/10 text-white')}><Users size={16} />Staff</button><button onClick={() => navigate('settings')} className={cn('flex w-full items-center gap-2.5 rounded-lg px-2.5 py-2.5 text-left text-[13px] font-semibold text-slate-400 hover:bg-white/10 hover:text-white', view === 'settings' && 'bg-white/10 text-white')}><Settings size={16} />Business settings</button></div>}</div><div className="border-t border-white/10 p-3"><div className="mb-2 flex items-center gap-2.5 rounded-lg bg-white/5 p-2.5"><span className="grid size-8 place-items-center rounded-full bg-indigo-400 text-[11px] font-black text-slate-950">{username.slice(0, 1).toUpperCase()}</span><div className="min-w-0"><strong className="block truncate text-[13px]">{username}</strong><span className="text-[11px] text-slate-400">{isAdmin ? 'Vendor Admin' : 'Staff'}</span></div></div><Button variant="ghost" className="w-full justify-start px-2.5 text-[13px] text-slate-400 hover:bg-white/10 hover:text-white" onClick={onSignOut}>Sign out</Button></div></aside>{open && <button className="fixed inset-0 z-30 bg-slate-950/50 lg:hidden" onClick={() => setOpen(false)} aria-label="Close menu overlay" />}<div className="lg:pl-64"><header className="sticky top-0 z-20 flex min-h-16 items-center gap-3 border-b border-slate-200 bg-white/90 px-4 py-3 backdrop-blur lg:px-6"><button className="rounded-lg p-1.5 hover:bg-slate-100 lg:hidden" onClick={() => setOpen(true)} aria-label="Open menu"><Menu size={20} /></button><div className="flex min-w-0 flex-1 flex-wrap items-center gap-2"><Store size={16} className="shrink-0 text-indigo-600" /><select className="max-w-[180px] rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[13px] font-bold outline-none focus:border-indigo-400" value={currentVendor?.id ?? ''} onChange={event => onVendorChange(Number(event.target.value))}>{vendors.map(vendor => <option key={vendor.id} value={vendor.id}>{vendor.name}</option>)}</select><ChevronDown size={14} className="-ml-6 pointer-events-none text-slate-400" /><select className="max-w-[180px] rounded-lg border border-slate-200 bg-white px-2.5 py-2 text-[13px] font-semibold outline-none focus:border-indigo-400" value={storeId ?? ''} onChange={event => onStoreChange(Number(event.target.value))}><option value="">All stores</option>{availableStores.map(store => <option key={store.id} value={store.id}>{store.name} · {store.code}</option>)}</select></div><div className="hidden items-center gap-2 text-[11px] font-semibold text-slate-500 sm:flex"><BookOpen size={14} /> {currentVendor?.name ?? 'No vendor selected'}</div></header><main className="mx-auto max-w-[1500px] p-4 lg:p-6">{children}</main></div></div>
}
